// Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
}

public boolean isSubtree(TreeNode root, TreeNode subRoot) {
    if (subRoot == null) return true;        // empty matches anything
    if (root == null) return false;          // nowhere left to match
    if (isSameTree(root, subRoot)) return true;  // matches at this anchor
    return isSubtree(root.left, subRoot)     // else search children
        || isSubtree(root.right, subRoot);
}

private boolean isSameTree(TreeNode p, TreeNode q) {
    if (p == null && q == null) return true;
    if (p == null || q == null) return false;
    return p.val == q.val
        && isSameTree(p.left, q.left)
        && isSameTree(p.right, q.right);
}

public boolean isSubtree(TreeNode root, TreeNode subRoot) {
    String text = serialize(root);
    String pattern = serialize(subRoot);
    return kmpContains(text, pattern);
}

private String serialize(TreeNode node) {
    StringBuilder sb = new StringBuilder();
    build(node, sb);
    return sb.toString();
}

private void build(TreeNode node, StringBuilder sb) {
    if (node == null) { sb.append('#'); return; }   // null marker (structure)
    sb.append('^').append(node.val);                 // delimiter prevents 1,2 vs 12
    build(node.left, sb);
    build(node.right, sb);
}

private boolean kmpContains(String text, String pat) {
    int[] lps = new int[pat.length()];
    for (int i = 1, len = 0; i < pat.length(); ) {   // build LPS table O(m)
        if (pat.charAt(i) == pat.charAt(len)) lps[i++] = ++len;
        else if (len > 0) len = lps[len - 1];
        else lps[i++] = 0;
    }
    for (int i = 0, j = 0; i < text.length(); ) {    // scan text O(n)
        if (text.charAt(i) == pat.charAt(j)) {
            i++; j++;
            if (j == pat.length()) return true;
        } else if (j > 0) j = lps[j - 1];
        else i++;
    }
    return false;
}

