def isSubtree(self, root: TreeNode, subRoot: TreeNode) -> bool:
    def serialize(node) -> str:
        if not node:
            return '#'                       # null marker (structure)
        return '^' + str(node.val) + serialize(node.left) + serialize(node.right)

    text = serialize(root)
    pattern = serialize(subRoot)
    return self.kmp_contains(text, pattern)

def kmp_contains(self, text: str, pat: str) -> bool:
    lps = [0] * len(pat)
    length = 0
    i = 1
    while i < len(pat):                      # build LPS table O(m)
        if pat[i] == pat[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length > 0:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    i = j = 0
    while i < len(text):                     # scan text O(n)
        if text[i] == pat[j]:
            i += 1
            j += 1
            if j == len(pat):
                return True
        elif j > 0:
            j = lps[j - 1]
        else:
            i += 1
    return False

