def isSubtree(self, root, subRoot):
    if not subRoot:
        return True
    if not root:
        return False
    if self.isSameTree(root, subRoot):  # full exact-subtree match
        return True
    return (self.isSubtree(root.left, subRoot)
            or self.isSubtree(root.right, subRoot))

